import type { ReactNode } from "react"
import { Button } from "@/shared/ui/button"
import { SparklesIcon } from "@/shared/ui/icon"

/**
 * 데스크톱 본문 아래 40px 줄(AppShell의 bottomBar). 끝에 에이전트를 여는 조용한 단추(보조 글자색), 앞에는 앱이 넣는 상태.
 * 휴대폰에는 두지 않는다(하단 탭 자리다).
 */
export function AgentBar({ label = "Agent", onOpen, children }: { label?: string; onOpen?: () => void; children?: ReactNode }) {
  return (
    <div className="flex h-10 shrink-0 items-center justify-end gap-2 px-3">
      {children && <div className="mr-auto flex min-w-0 items-center gap-2 text-xs text-muted-foreground">{children}</div>}
      <Button variant="ghost" size="sm" className="text-muted-foreground" onClick={onOpen}>
        <SparklesIcon data-icon="inline-start" />
        {label}
      </Button>
    </div>
  )
}

import { useMemo, useState, type CSSProperties, type ReactNode } from "react"
import { useIsMobile } from "@/shared/lib/use-mobile"
import { cn } from "cn"
import { PageChromeProvider } from "@/shared/ui/page"
import { SidebarProvider } from "@/shared/ui/sidebar"
import { TooltipProvider } from "@/shared/ui/tooltip"
import { MeButton, type ShellMe } from "./MeMenu"
import { MobileTabBar } from "./MobileTabBar"
import { currentEntry, type NavEntry, type NavSpace } from "./nav"
import { ShellSidebar, type FoldSlot, type OpenGroups, type ShellLayout } from "./ShellSidebar"
import { SidebarResizeHandle } from "./SidebarResizeHandle"

/** 사이드바 너비(루트 16px 기준 px): 처음과 다시 펼칠 때 initial, 끌어서 min~max(호호코워크 340 · 220~380). */
export type SidebarWidth = { initial: number; min: number; max: number }
const SIDEBAR_WIDTH: SidebarWidth = { initial: 340, min: 220, max: 380 }

export type AppShellProps = {
  /** 지금 주소의 메뉴 한 벌(주 메뉴 또는 하위 공간). 앱이 주소로 고른다. */
  space: NavSpace
  /** 지금 주소. 지금 항목을 찾고, 바뀌면 더보기를 닫는다. */
  pathname: string
  /** 사이드바 머리의 로고 · 이름(홈 링크로 감싸 넘긴다). 접힌 사이드바는 심벌만. */
  brand: FoldSlot
  /** 사이드바 머리 줄 오른쪽 작은 도구(전역 검색). */
  headerTools?: ReactNode
  /** 내 박스 · 아바타와 내 메뉴. 휴대폰은 앱 바 끝의 아바타. */
  me?: ShellMe
  /** 사이드바 바닥 왼쪽(릴리스 · 환경 설정). */
  footer?: FoldSlot
  /** 데스크톱 본문 아래 줄(AgentBar). inset에서는 본문 면 아래, split에서는 본문 아래 끝에 붙는다. */
  bottomBar?: ReactNode
  /** 휴대폰 앱 바 오른쪽 공통 도구(검색 · 알림함). 내 아바타는 me가 있으면 끝에 붙는다. */
  phoneTools?: ReactNode
  /** 휴대폰 하단 탭. 없으면 공간 메뉴의 앞 네 곳(isPhoneHidden 제외). */
  tabs?: NavEntry[]
  /** inset: 바닥 위에 떠 있는 둥근 본문 면. split: 가는 선으로 나눈 평평한 면. */
  layout?: ShellLayout
  openGroups?: OpenGroups
  sidebarWidth?: SidebarWidth
  /** 페이지(라우터의 Outlet). */
  children: ReactNode
}

/**
 * 앱 셸(호호코워크 AppFrame · inset 레이아웃). 메뉴는 데이터(space)로 받고, 로고 · 나 · 도구 · 바닥 줄은 자리로 받는다.
 * - 데스크톱: 끌어 220~380px로 바꾸는 사이드바(접으면 아이콘만, 다시 펼치면 처음 너비)와 본문. inset은 바닥(사이드바 색) 위에
 *   위 · 오른쪽 8px 띄운 초타원 면, split은 선으로 나눈 면이다. Ctrl/⌘+B로도 접는다.
 * - 휴대폰(64rem 미만): 사이드바 없이 본문과 하단 탭(앞 네 곳 + 더보기). 위쪽 52px 앱 바는 Page가 그리고 오른쪽 도구는 여기서 넘긴다.
 *   상세 · 양식 페이지가 전체 화면을 알리면(useFullScreen) 하단 탭을 치운다.
 * 본문의 부모 요소는 분기점 · 배치가 바뀌어도 같은 자리에 같은 종류로 두어, 창을 줄이고 늘려도 작성 중인 페이지가 다시 마운트되지 않는다.
 */
export function AppShell({ space, pathname, brand, headerTools, me, footer, bottomBar, phoneTools, tabs, layout = "inset", openGroups = "all",
  sidebarWidth = SIDEBAR_WIDTH, children }: AppShellProps) {
  const isMobile = useIsMobile()
  const [isFullScreen, setFullScreen] = useState(false)
  const [isOpen, setIsOpen] = useState(true)
  const [width, setWidth] = useState(sidebarWidth.initial)
  const [isResizing, setIsResizing] = useState(false)
  const current = currentEntry(space, pathname)
  const tools = useMemo(() => (phoneTools || me ? <>{phoneTools}{me && <MeButton me={me} className="mx-0.5" />}</> : null), [phoneTools, me])
  const chrome = useMemo(() => ({ tools, setFullScreen }), [tools])
  const open = (next: boolean) => {
    setIsOpen(next)
    if (next) setWidth(sidebarWidth.initial)
  }
  const isInset = layout === "inset"
  return (
    <TooltipProvider>
      <PageChromeProvider value={chrome}>
        {/* check-ui: allow-style 사이드바 너비는 사용자가 끌어 정한 값이다(rem이라 큰 화면의 루트 배율을 따른다). */}
        <SidebarProvider open={isOpen} onOpenChange={open} style={{ "--sidebar-width": `${width / 16}rem` } as CSSProperties}
          // 끄는 동안에는 너비 전환 애니메이션을 끈다(손을 바로 따라가도록).
          className={cn("h-svh min-h-0 overflow-hidden", isMobile || !isInset ? "bg-background" : "bg-sidebar",
            isResizing && "**:data-[slot=sidebar-container]:transition-none **:data-[slot=sidebar-gap]:transition-none")}>
          {!isMobile && <ShellSidebar space={space} current={current} brand={brand} headerTools={headerTools} me={me} footer={footer}
            layout={layout} openGroups={openGroups} />}
          {!isMobile && isOpen && <SidebarResizeHandle value={width} min={sidebarWidth.min} max={sidebarWidth.max} onChange={setWidth}
            onDraggingChange={setIsResizing} />}
          <div className="flex min-w-0 flex-1 flex-col">
            <main className={cn("flex min-h-0 flex-1 flex-col overflow-hidden bg-background",
              isMobile && "pt-[env(safe-area-inset-top)] pr-[env(safe-area-inset-right)] pl-[env(safe-area-inset-left)]",
              !isMobile && isInset && cn("mt-2 mr-2 squircle rounded-surface shadow-surface", !bottomBar && "mb-2"))}>
              {children}
            </main>
            {!isMobile && bottomBar}
            {isMobile && !isFullScreen && <MobileTabBar space={space} current={current} tabs={tabs} pathname={pathname} />}
          </div>
        </SidebarProvider>
      </PageChromeProvider>
    </TooltipProvider>
  )
}

import type { ReactElement, ReactNode } from "react"
import { cn } from "cn"
import { Avatar, AvatarFallback, AvatarImage } from "@/shared/ui/avatar"
import { DropdownMenu, DropdownMenuContent, DropdownMenuTrigger } from "@/shared/ui/dropdown-menu"
import { MoreVerticalIcon } from "@/shared/ui/icon"
import { Skeleton } from "@/shared/ui/skeleton"

/**
 * 셸이 보이는 나. 펼친 사이드바는 내 박스(아바타 · 이름 · 소속 · …), 접은 사이드바와 휴대폰 앱 바는 아바타만 그리고,
 * 어느 쪽을 눌러도 같은 내 메뉴(menu: DropdownMenuGroup · DropdownMenuItem들)가 열린다. 읽는 동안은 name 없이 넘긴다.
 */
export type ShellMe = {
  name?: string
  /** 이름 아래 한 줄(소속 · 메일). */
  detail?: string
  picture?: string
  /** 그림이 없을 때의 글자. 없으면 이름 끝 두 글자(한국어 이름의 부르는 이름). */
  initials?: string
  menu: ReactNode
}

const initialsOf = (me: ShellMe) => me.initials ?? me.name?.slice(-2) ?? ""

/** 내 메뉴: trigger(내 박스 · 아바타 단추)를 누르면 연다. */
export function MeMenu({ me, trigger }: { me: ShellMe; trigger: ReactElement }) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={trigger} />
      <DropdownMenuContent align="start" className="min-w-48">{me.menu}</DropdownMenuContent>
    </DropdownMenu>
  )
}

/** 내 아바타(32px 초타원). */
export function MeAvatar({ me }: { me: ShellMe }) {
  return (
    <Avatar className="size-8 squircle rounded-[0.625rem] after:rounded-[0.625rem]">
      {me.picture && <AvatarImage src={me.picture} alt="" className="squircle rounded-[0.625rem]" />}
      <AvatarFallback className="squircle rounded-[0.625rem] bg-secondary text-xs font-semibold">{initialsOf(me)}</AvatarFallback>
    </Avatar>
  )
}

/** 펼친 사이드바의 내 박스: 아바타 · 이름 · 한 줄 · 가로 …, 누르면 내 메뉴. */
export function MeBox({ me }: { me: ShellMe }) {
  return (
    <MeMenu me={me} trigger={
      <button type="button" aria-label={me.name ? `내 메뉴: ${me.name}` : "내 메뉴"}
        className="flex w-full items-center gap-2.5 squircle rounded-xl bg-pressed px-2.5 py-2 text-left outline-none hover:bg-[color-mix(in_srgb,var(--foreground)_10%,transparent)] focus-visible:ring-2 focus-visible:ring-ring">
        <MeAvatar me={me} />
        <span className="flex min-w-0 flex-1 flex-col">
          {me.name ? (
            <>
              <span className="truncate text-sm font-semibold">{me.name}</span>
              {me.detail && <span className="truncate text-xs text-muted-foreground">{me.detail}</span>}
            </>
          ) : (
            <>
              <Skeleton className="my-0.5 h-4 w-16" />
              <Skeleton className="my-0.5 h-3 w-12" />
            </>
          )}
        </span>
        <MoreVerticalIcon className="rotate-90 text-icon-muted" />
      </button>
    } />
  )
}

/** 아바타만 있는 내 메뉴 단추(접은 사이드바 · 휴대폰 앱 바). 휴대폰에서는 44px 누름 자리를 둔다. */
export function MeButton({ me, className }: { me: ShellMe; className?: string }) {
  return (
    <MeMenu me={me} trigger={
      <button type="button" aria-label="내 메뉴" className={cn("grid place-items-center rounded-xl outline-none focus-visible:ring-2 focus-visible:ring-ring max-md:size-11", className)}>
        <MeAvatar me={me} />
      </button>
    } />
  )
}

import { Link } from "@tanstack/react-router"
import { useEffect, useState } from "react"
import { cn } from "cn"
import { Button } from "@/shared/ui/button"
import { Drawer, DrawerClose, DrawerContent, DrawerHeader, DrawerTitle } from "@/shared/ui/drawer"
import { ArrowLeftIcon, FileTextIcon, MoreHorizontalIcon, XIcon } from "@/shared/ui/icon"
import { badgeText, contains, EXACT_LINK, phoneEntriesOf, type NavEntry, type NavSpace } from "./nav"

const tabClass = (isCurrent: boolean) => cn(
  "relative flex h-14 min-w-0 flex-1 flex-col items-center justify-center gap-0.5 text-[0.6875rem] font-medium text-muted-foreground outline-none",
  "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-inset aria-disabled:text-muted-foreground/50",
  isCurrent && "text-foreground",
)

/**
 * 휴대폰 하단 탭(64rem 미만): 공간 메뉴의 앞 네 곳(tabs로 바꿀 수 있다)과 더보기. 엄지가 닿는 아래에 두고 홈 표시줄을 피한다.
 * 고른 탭과 열린 더보기는 진한 글자와 Bold Duotone이다. 더보기는 나머지 목적지를 바텀시트 한 목록으로 보이고, 하위 공간이면
 * 공간 이름을 제목으로, 맨 위에 돌아가기를 둔다. 아래 줄은 위 항목 아래 들여 쓴 묶음으로 남긴다(위 항목이 탭에 있어도 묶음 머리로 다시 보인다).
 */
export function MobileTabBar({ space, current, tabs: chosenTabs, pathname }: {
  space: NavSpace; current: NavEntry | undefined; tabs?: NavEntry[]
  /** 주소가 바뀌면 더보기를 닫는다. */
  pathname: string
}) {
  const [isMoreOpen, setMoreOpen] = useState(false)
  useEffect(() => setMoreOpen(false), [pathname])
  const entries = phoneEntriesOf(space)
  const tabs = chosenTabs ?? entries.slice(0, 4)
  const more = entries.flatMap(entry => {
    const isTab = tabs.includes(entry)
    const children = entry.children ?? []
    return isTab && children.length === 0 ? [] : [{ entry, isTab }]
  })
  const hasMore = more.length > 0 || Boolean(space.back)
  const isMoreChosen = isMoreOpen || Boolean(current && !tabs.some(tab => contains(tab, current)))
  const title = space.back ? space.title : "더보기"
  const close = () => setMoreOpen(false)
  return (
    <>
      <nav aria-label="주 메뉴" className="flex shrink-0 border-t bg-background pr-[env(safe-area-inset-right)] pb-[env(safe-area-inset-bottom)] pl-[env(safe-area-inset-left)]">
        {tabs.map(entry => <Tab key={`${entry.path}:${entry.label}`} entry={entry} isCurrent={contains(entry, current)} />)}
        {hasMore && (
          <button type="button" aria-haspopup="dialog" aria-expanded={isMoreOpen} onClick={() => setMoreOpen(true)} className={tabClass(isMoreChosen)}>
            <MoreHorizontalIcon chosen={isMoreChosen} className="size-6" />
            <span>더보기</span>
          </button>
        )}
      </nav>
      <Drawer open={isMoreOpen} onOpenChange={setMoreOpen}>
        <DrawerContent>
          <DrawerHeader className="flex-row items-center gap-2 px-3 pt-3 pb-1 text-left">
            <DrawerTitle className="min-w-0 flex-1 truncate px-2 text-left text-base font-semibold">{title}</DrawerTitle>
            <DrawerClose render={<Button variant="ghost" size="icon" aria-label="메뉴 닫기" className="size-11" />}><XIcon className="size-5" /></DrawerClose>
          </DrawerHeader>
          <nav aria-label={title} className="min-h-0 overflow-y-auto px-3 pb-[calc(1.25rem+env(safe-area-inset-bottom))]">
            <ul className="flex flex-col">
              {space.back && (
                <li>
                  <Link to={space.back.path} activeOptions={EXACT_LINK} onClick={close} className={rowClass}>
                    <ArrowLeftIcon className="size-5 shrink-0" />
                    <span className="truncate">{space.back.label}</span>
                  </Link>
                </li>
              )}
              {more.map(({ entry }, index) => {
                const hasChildren = (entry.children?.length ?? 0) > 0
                const previousHasChildren = index > 0 && (more[index - 1].entry.children?.length ?? 0) > 0
                return (
                  // 아래 줄이 있는 묶음은 앞뒤를 가는 선으로 나눈다(접힌 사이드바가 묶음을 선으로 나누는 것과 같다).
                  <li key={`${entry.path}:${entry.label}`} className={cn((hasChildren || previousHasChildren) && (index > 0 || space.back) && "mt-2 border-t pt-2")}>
                    <MoreRow entry={entry} current={current} depth={0} onPick={close} />
                  </li>
                )
              })}
            </ul>
          </nav>
        </DrawerContent>
      </Drawer>
    </>
  )
}

function Tab({ entry, isCurrent }: { entry: NavEntry; isCurrent: boolean }) {
  const Icon = entry.icon ?? FileTextIcon
  const body = (
    <>
      <Icon chosen={isCurrent} className="size-6" />
      <span className="max-w-full truncate px-1">{entry.label}</span>
      {entry.badge ? <span className="absolute top-1.5 left-[calc(50%+0.5rem)] min-w-4 rounded-full bg-foreground px-1 text-[0.625rem] leading-4 text-background tabular-nums">{badgeText(entry.badge)}</span> : null}
    </>
  )
  if (entry.isDisabled) return <span aria-disabled className={tabClass(false)}>{body}</span>
  return <Link to={entry.path} search={entry.search as never} activeOptions={EXACT_LINK} aria-current={isCurrent ? "page" : undefined} className={tabClass(isCurrent)}>{body}</Link>
}

const rowClass = cn(
  "flex h-12 min-w-0 items-center gap-3 squircle rounded-xl px-3 text-base text-muted-foreground outline-none",
  "hover:bg-accent hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring aria-[current=page]:bg-pressed aria-[current=page]:font-medium aria-[current=page]:text-foreground",
  "aria-disabled:text-muted-foreground/50 aria-disabled:hover:bg-transparent",
)

const INDENT = ["", "pl-11", "pl-19", "pl-27"]

/** 더보기의 줄 하나와 그 아래 줄. 아래 줄은 위 항목의 글자 시작선에 맞춰 들인다(사이드바와 같은 위계). */
function MoreRow({ entry, current, depth, onPick }: { entry: NavEntry; current: NavEntry | undefined; depth: number; onPick: () => void }) {
  const isCurrent = entry === current
  const children = entry.children ?? []
  const mark = entry.media ?? (entry.icon ? <entry.icon chosen={isCurrent} className="size-5 shrink-0" /> : null)
  // 들여쓰기는 단계마다 아이콘(20px) + 간격(12px)이라 위 항목의 글자 시작선에 선다.
  const indent = INDENT[Math.min(depth, INDENT.length - 1)]
  const body = (
    <>
      {mark}
      <span className="min-w-0 flex-1 truncate">{entry.label}</span>
      {entry.badge ? <span className="text-sm text-muted-foreground tabular-nums">{badgeText(entry.badge)}</span> : null}
    </>
  )
  return (
    <>
      {entry.isDisabled
        ? <span aria-disabled className={cn(rowClass, indent)}>{body}</span>
        : (
          <Link to={entry.path} search={entry.search as never} activeOptions={EXACT_LINK} onClick={onPick} aria-current={isCurrent ? "page" : undefined} className={cn(rowClass, indent)}>
            {body}
          </Link>
        )}
      {children.length > 0 && (
        <ul className="flex flex-col">
          {children.map(child => <li key={`${child.path}:${child.label}`}><MoreRow entry={child} current={current} depth={depth + 1} onPick={onPick} /></li>)}
        </ul>
      )}
    </>
  )
}

import { Collapsible } from "@base-ui/react/collapsible"
import { Link } from "@tanstack/react-router"
import { useEffect, useState, type ReactNode } from "react"
import { cn } from "cn"
import { Button } from "@/shared/ui/button"
import { ArrowLeftIcon, ChevronDownIcon, ChevronsLeftIcon, ChevronsRightIcon } from "@/shared/ui/icon"
import {
  Sidebar, SidebarContent, SidebarFooter, SidebarGroup, SidebarGroupContent, SidebarGroupLabel, SidebarHeader,
  SidebarMenu, SidebarMenuAction, SidebarMenuBadge, SidebarMenuButton, SidebarMenuItem, SidebarMenuSub, SidebarMenuSubButton,
  SidebarMenuSubItem, SidebarSeparator, useSidebar,
} from "@/shared/ui/sidebar"
import { MeBox, MeButton, type ShellMe } from "./MeMenu"
import { badgeText, contains, entriesOf, EXACT_LINK, type NavEntry, type NavSpace } from "./nav"

export type ShellLayout = "inset" | "split"
/** 'all'은 아래 줄 묶음을 모두 펼친다(메뉴가 짧은 업무 앱). 'current'는 지금 자리의 묶음만(묶음이 많은 문서 사이트). */
export type OpenGroups = "all" | "current"
/** 접힌 사이드바에도 그리는 자리는 접힘 여부를 받는다. */
export type FoldSlot = ReactNode | ((isFolded: boolean) => ReactNode)

const slot = (value: FoldSlot | undefined, isFolded: boolean) => (typeof value === "function" ? value(isFolded) : value)
const keyOf = (entry: NavEntry) => (entry.search ? `${entry.path}?${new URLSearchParams(entry.search)}` : entry.path)

/** 지금 자리까지 내려가는 묶음들(위에서부터). 모두 열어 지금 자리가 보이게 한다. */
function trailTo(list: readonly NavEntry[], current: NavEntry | undefined): string[] {
  for (const entry of list) {
    if (!entry.children?.length || !contains(entry, current)) continue
    return [keyOf(entry), ...trailTo(entry.children, current)]
  }
  return []
}

type Groups = { isOpen: (entry: NavEntry) => boolean | undefined; setOpen: (entry: NavEntry, isOpen: boolean) => void }

/**
 * 'current'의 펼침 상태. 다른 묶음 안으로 옮겨 가면 그 묶음도 펼치고, 사용자가 연 묶음은 그대로 둔다.
 * 'all'은 펼침을 부품에 맡긴다(처음에 모두 펼침).
 */
function useGroups(mode: OpenGroups, entries: readonly NavEntry[], current: NavEntry | undefined): Groups {
  const trail = trailTo(entries, current).join("\n")
  const [open, setOpenKeys] = useState(() => new Set(trail ? trail.split("\n") : []))
  useEffect(() => {
    if (!trail) return
    setOpenKeys(keys => (trail.split("\n").every(key => keys.has(key)) ? keys : new Set([...keys, ...trail.split("\n")])))
  }, [trail])
  if (mode === "all") return { isOpen: () => undefined, setOpen: () => {} }
  return {
    isOpen: entry => open.has(keyOf(entry)),
    setOpen: (entry, isOpen) => setOpenKeys(keys => {
      const next = new Set(keys)
      if (isOpen) next.add(keyOf(entry))
      else next.delete(keyOf(entry))
      return next
    }),
  }
}

export type ShellSidebarProps = {
  space: NavSpace
  current: NavEntry | undefined
  /** 머리의 로고 · 이름(홈 링크는 앱이 감싼다). 접힌 사이드바는 표시만 남긴다. */
  brand: FoldSlot
  /** 머리 줄 오른쪽 작은 도구(전역 검색). 접히면 로고 아래로 내려간다. */
  headerTools?: ReactNode
  me?: ShellMe
  /** 바닥 왼쪽(릴리스 · 환경). 접기 단추는 셸이 둔다. */
  footer?: FoldSlot
  layout: ShellLayout
  openGroups: OpenGroups
}

/**
 * 데스크톱 사이드바(호호코워크 AppFrame). 머리: 로고 · 도구, 그 아래 내 박스. 몸: 공간의 메뉴(하위 공간이면 맨 위에 ← 공간 이름),
 * 아래 줄이 있는 항목은 오른쪽 끝 꺾쇠로 접고 편다. 바닥: 앱의 한 줄과 접기. 접으면 아이콘만 남고 묶음 사이를 가는 선으로 나눈다.
 */
export function ShellSidebar({ space, current, brand, headerTools, me, footer, layout, openGroups }: ShellSidebarProps) {
  const { state, toggleSidebar } = useSidebar()
  const isFolded = state === "collapsed"
  const groups = useGroups(openGroups, entriesOf(space), current)
  const foldLabel = isFolded ? "사이드바 펼치기" : "사이드바 접기"
  return (
    <Sidebar collapsible="icon" variant={layout === "inset" ? "inset" : "sidebar"} aria-label="주 메뉴">
      <SidebarHeader className={cn("gap-3 px-3 group-data-[collapsible=icon]:px-2", layout === "inset" ? "pt-3" : "pt-0")}>
        {/* split은 머리 줄을 페이지 머리 줄(52px)과 같은 선에 둔다. */}
        <div className={cn("flex items-center justify-between gap-2 group-data-[collapsible=icon]:h-auto group-data-[collapsible=icon]:flex-col",
          layout === "inset" ? "h-8" : "h-13 group-data-[collapsible=icon]:pt-3")}>
          <div className="flex min-w-0 items-center">{slot(brand, isFolded)}</div>
          {headerTools && <div className="flex shrink-0 items-center gap-1 group-data-[collapsible=icon]:flex-col">{headerTools}</div>}
        </div>
        {me && (isFolded ? <MeButton me={me} className="mx-auto" /> : <MeBox me={me} />)}
      </SidebarHeader>
      <SidebarContent className="px-1">
        {space.back && (
          <SidebarGroup className="py-1">
            <SidebarMenu>
              <SidebarMenuItem>
                <SidebarMenuButton tooltip={space.back.label} aria-label={`${space.back.label}: ${space.title}`}
                  render={<Link to={space.back.path} activeOptions={EXACT_LINK} />} className="font-semibold">
                  <ArrowLeftIcon />
                  <span>{space.title}</span>
                </SidebarMenuButton>
              </SidebarMenuItem>
            </SidebarMenu>
          </SidebarGroup>
        )}
        {space.sections.map((section, index) => (
          <SidebarGroup key={section.title} className="py-1">
            {isFolded && (index > 0 || space.back) && <SidebarSeparator className="mx-2 mb-1" />}
            {!section.isHeaderHidden && <SidebarGroupLabel>{section.title}</SidebarGroupLabel>}
            <SidebarGroupContent>
              <SidebarMenu className="gap-0.5">
                {section.entries.map(entry => <TopItem key={keyOf(entry)} entry={entry} current={current} groups={groups} />)}
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        ))}
      </SidebarContent>
      <SidebarFooter className="flex-row items-center justify-between px-3 pb-2 group-data-[collapsible=icon]:flex-col group-data-[collapsible=icon]:justify-center">
        <div className="flex min-w-0 items-center gap-1 text-xs text-muted-foreground group-data-[collapsible=icon]:flex-col">{slot(footer, isFolded)}</div>
        <Button variant="ghost" size="icon-sm" aria-label={foldLabel} title={`${foldLabel} (Ctrl+B)`} onClick={toggleSidebar}>
          {isFolded ? <ChevronsRightIcon /> : <ChevronsLeftIcon />}
        </Button>
      </SidebarFooter>
    </Sidebar>
  )
}

/** 항목의 그림: media(프로젝트 표식)가 먼저, 없으면 아이콘(지금 자리면 Bold Duotone). */
function EntryMark({ entry, isCurrent }: { entry: NavEntry; isCurrent: boolean }) {
  if (entry.media) return <>{entry.media}</>
  return entry.icon ? <entry.icon chosen={isCurrent} /> : null
}

const linkOf = (entry: NavEntry) => (entry.isDisabled ? undefined : <Link to={entry.path} search={entry.search as never} activeOptions={EXACT_LINK} />)

/** 아래 줄을 접고 펴는 꺾쇠(오른쪽 끝). 접힌 동안 오른쪽을 가리킨다. */
function GroupTrigger({ entry }: { entry: NavEntry }) {
  return (
    <Collapsible.Trigger aria-label={`${entry.label} 아래 메뉴`} render={<SidebarMenuAction />}
      className="[&>svg]:transition-transform not-data-panel-open:[&>svg]:-rotate-90">
      <ChevronDownIcon />
    </Collapsible.Trigger>
  )
}

/**
 * 최상위 항목. 아래 줄이 지금 자리여도 함께 칠해 어느 묶음 안인지 보인다(호호코워크). 아래 줄이 있으면 처음에 펼친다
 * ('current'는 지금 자리의 묶음만).
 */
function TopItem({ entry, current, groups }: { entry: NavEntry; current: NavEntry | undefined; groups: Groups }) {
  const isCurrent = contains(entry, current)
  const children = entry.children ?? []
  const button = (
    <SidebarMenuButton isActive={isCurrent} tooltip={entry.label} disabled={entry.isDisabled}
      aria-current={entry === current ? "page" : undefined} render={linkOf(entry)}>
      <EntryMark entry={entry} isCurrent={isCurrent} />
      <span>{entry.label}</span>
    </SidebarMenuButton>
  )
  const badge = entry.badge ? <SidebarMenuBadge className={cn(children.length > 0 && "right-7")}>{badgeText(entry.badge)}</SidebarMenuBadge> : null
  if (children.length === 0) return <SidebarMenuItem>{button}{badge}</SidebarMenuItem>
  return (
    <Collapsible.Root defaultOpen open={groups.isOpen(entry)} onOpenChange={isOpen => groups.setOpen(entry, isOpen)} render={<SidebarMenuItem />}>
      {button}
      {badge}
      <GroupTrigger entry={entry} />
      <Collapsible.Panel>
        <SidebarMenuSub>
          {children.map(child => <SubItem key={keyOf(child)} entry={child} current={current} groups={groups} />)}
        </SidebarMenuSub>
      </Collapsible.Panel>
    </Collapsible.Root>
  )
}

/** 아래 줄. 다시 아래 줄이 있으면 같은 꺾쇠로 접고, 그 안의 줄은 한 단계 더 들인다. */
function SubItem({ entry, current, groups }: { entry: NavEntry; current: NavEntry | undefined; groups: Groups }) {
  const isCurrent = entry === current
  const children = entry.children ?? []
  const button = (
    <SidebarMenuSubButton isActive={isCurrent} aria-current={isCurrent ? "page" : undefined} aria-disabled={entry.isDisabled || undefined}
      render={linkOf(entry) ?? <span />} className={cn(children.length > 0 && "pr-8", entry.badge && "pr-8")}>
      <EntryMark entry={entry} isCurrent={isCurrent} />
      <span>{entry.label}</span>
    </SidebarMenuSubButton>
  )
  const badge = entry.badge ? <SidebarMenuBadge className={cn("top-1", children.length > 0 && "right-7")}>{badgeText(entry.badge)}</SidebarMenuBadge> : null
  if (children.length === 0) return <SidebarMenuSubItem>{button}{badge}</SidebarMenuSubItem>
  return (
    <Collapsible.Root defaultOpen open={groups.isOpen(entry)} onOpenChange={isOpen => groups.setOpen(entry, isOpen)} render={<SidebarMenuSubItem />}>
      {button}
      {badge}
      <GroupTrigger entry={entry} />
      <Collapsible.Panel>
        <SidebarMenuSub className="mr-0 pr-0">
          {children.map(child => <SubItem key={keyOf(child)} entry={child} current={current} groups={groups} />)}
        </SidebarMenuSub>
      </Collapsible.Panel>
    </Collapsible.Root>
  )
}

import { useRef, useState, type KeyboardEvent, type PointerEvent } from "react"

const STEP = 16

/** 루트 글자 크기의 배율. 큰 화면(1920px 이상)은 루트를 키우므로 화면 px를 기준 px로 되돌릴 때 쓴다. */
const rootScale = () => parseFloat(getComputedStyle(document.documentElement).fontSize) / 16 || 1

/**
 * 사이드바 오른쪽 가장자리의 너비 손잡이(Linear처럼 가장자리를 끈다). 끌거나, 초점을 두고 ← → (Shift는 4배) · Home · End.
 * inset 바닥에는 선이 없으므로 평소에는 보이지 않고, 가리킬 때 · 끄는 동안 · 키보드 초점에서만 선이 선다.
 * 값은 루트 16px 기준 px이다. 사이드바 너비를 rem으로 두므로 큰 화면에서 루트가 커지면 끄는 거리도 그만큼 나눈다.
 * (PaneResizeHandle은 늘 선을 그리는 칸 구분선이라 따로 둔다.)
 */
export function SidebarResizeHandle({ value, min, max, onChange, onDraggingChange }: {
  value: number; min: number; max: number; onChange: (width: number) => void; onDraggingChange: (isDragging: boolean) => void
}) {
  const start = useRef<{ x: number; width: number; scale: number } | null>(null)
  const [isDragging, setIsDragging] = useState(false)
  const resize = (width: number) => onChange(Math.round(Math.min(max, Math.max(min, width))))
  const drag = (next: boolean) => {
    setIsDragging(next)
    onDraggingChange(next)
  }

  const onPointerDown = (event: PointerEvent<HTMLDivElement>) => {
    if (event.button !== 0) return
    event.preventDefault()
    event.currentTarget.setPointerCapture(event.pointerId)
    start.current = { x: event.clientX, width: value, scale: rootScale() }
    drag(true)
  }
  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => {
    const at = start.current
    if (at) resize(at.width + (event.clientX - at.x) / at.scale)
  }
  const onPointerEnd = () => {
    start.current = null
    drag(false)
  }
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const step = event.shiftKey ? STEP * 4 : STEP
    const next = { ArrowLeft: value - step, ArrowRight: value + step, Home: min, End: max }[event.key]
    if (next === undefined) return
    event.preventDefault()
    resize(next)
  }

  return (
    <div role="separator" aria-orientation="vertical" aria-label="사이드바 너비" aria-valuenow={value} aria-valuemin={min} aria-valuemax={max}
      tabIndex={0} data-dragging={isDragging || undefined}
      onPointerDown={onPointerDown} onPointerMove={onPointerMove} onPointerUp={onPointerEnd} onPointerCancel={onPointerEnd} onKeyDown={onKeyDown}
      className="group/handle relative z-20 -mx-1 flex w-2 shrink-0 cursor-col-resize touch-none justify-center outline-none">
      <span className="w-0.5 transition-colors group-hover/handle:bg-border group-focus-visible/handle:bg-ring group-data-dragging/handle:bg-ring" />
    </div>
  )
}

import type { ReactNode } from "react"
import type { Icon } from "@/shared/ui/icon"

/**
 * 메뉴의 목적지 하나. children은 펼치는 아래 줄(별표한 프로젝트 · 저장한 뷰 · 문서 묶음)이며 몇 단계든 된다.
 * 같은 주소의 다른 뷰(?view=)처럼 주소만으로 지금 자리를 가릴 수 없으면 isCurrent로 직접 정한다.
 */
export type NavEntry = {
  path: string
  /** 같은 페이지의 다른 조건(?view=). 링크에 붙고, 지금 자리 판단에는 쓰지 않는다. */
  search?: Record<string, string>
  label: string
  /** 아래 줄은 아이콘을 생략할 수 있다(위 항목 아래에 들여 쓴다). */
  icon?: Icon
  /** 아이콘 대신 그릴 것(프로젝트 표식). */
  media?: ReactNode
  /** 옆의 수(읽지 않은 알림). 99를 넘으면 99+. */
  badge?: number
  isDisabled?: boolean
  /** 지금 자리를 직접 정한다. 없으면 주소의 가장 긴 접두사로 찾는다. */
  isCurrent?: boolean
  /** 휴대폰 하단 탭 · 더보기에 넣지 않는다(앱 바 도구가 같은 곳을 연다: 알림함). */
  isPhoneHidden?: boolean
  children?: NavEntry[]
}

/** 이름 있는 묶음. 첫 묶음처럼 이름이 필요 없으면 isHeaderHidden. */
export type NavSection = { title: string; isHeaderHidden?: boolean; entries: NavEntry[] }

/**
 * 화면에 보이는 메뉴 한 벌. 주 메뉴, 또는 주 메뉴에서 연 하위 공간(내 계정 · 프로젝트 · 관리)이 주 메뉴를 대체하고
 * back으로 돌아간다. 어느 공간인지는 앱이 주소로 정해 넘긴다.
 */
export type NavSpace = { id: string; title: string; back?: { label: string; path: string }; sections: NavSection[] }

/** 공간의 최상위 항목들(묶음 순서대로). */
export const entriesOf = (space: NavSpace) => space.sections.flatMap(section => section.entries)

/** 모든 단계의 항목을 위에서부터 한 줄로. */
export const flattenEntries = (list: readonly NavEntry[]): NavEntry[] => list.flatMap(entry => [entry, ...flattenEntries(entry.children ?? [])])

const baseOf = (path: string) => path.split("?")[0]

/**
 * 주소에 해당하는 항목: isCurrent를 정한 항목은 그것을 따르고, 나머지는 항목 주소이거나 그 아래인 것 중 가장 긴 것.
 * 같은 주소의 뷰 줄(search가 있는 줄)은 접두사 판단에서 빼 위 항목이 지금 자리가 된다.
 */
export function currentEntry(space: NavSpace, pathname: string): NavEntry | undefined {
  const all = flattenEntries(entriesOf(space))
  const chosen = all.find(entry => entry.isCurrent)
  if (chosen) return chosen
  return all
    .filter(entry => entry.isCurrent === undefined && !entry.search)
    .filter(entry => pathname === baseOf(entry.path) || pathname.startsWith(`${baseOf(entry.path)}/`))
    .sort((a, b) => baseOf(b.path).length - baseOf(a.path).length)[0]
}

/** entry나 그 아래 어딘가가 target인지. 위 항목을 함께 칠하고, 탭이 지금 자리인지 볼 때 쓴다. */
export const contains = (entry: NavEntry, target: NavEntry | undefined): boolean =>
  !!target && (entry === target || (entry.children ?? []).some(child => contains(child, target)))

/** 휴대폰 탭과 더보기에 둘 수 있는 최상위 항목. */
export const phoneEntriesOf = (space: NavSpace) => entriesOf(space).filter(entry => !entry.isPhoneHidden)

export const badgeText = (count: number) => (count > 99 ? "99+" : String(count))

/**
 * 메뉴 링크의 activeOptions. TanStack Link는 기본으로 주소의 접두사가 같으면 스스로 aria-current="page"를 단다. 그러면 위 항목과
 * 지금 항목이 함께 "지금 페이지"로 읽히므로, 링크는 주소와 검색 값이 똑같을 때만 스스로 달고 나머지는 셸이 정한다.
 */
export const EXACT_LINK = { exact: true, includeSearch: true } as const
